import React, { useState, useMemo, useEffect } from "react";
import {
  Box,
  Typography,
  IconButton,
  Tooltip,
  Chip,
  alpha,
  useTheme,
  Divider,
  Stack,
} from "@mui/material";
import {
  Visibility as ViewIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Stars as CoinIcon,
  EmojiEvents as BadgeIcon,
  AccountCircle as ProfileIcon,
  Star as RarityIcon,
  MilitaryTech as LevelIcon,
  List as ListIcon,
  HelpOutline as TipsIcon,
  ErrorOutline as PitfallIcon,
  TrackChanges as GoalIcon,
} from "@mui/icons-material";
import DataTable from "../../../components/DataTable";
import DetailsModal from "../../../components/DetailsModal";
import ConfirmationModal from "../../../components/ConfirmationModal";
import BadgeModal from "../../../components/page_components/BadgeModal";
import { toast } from "react-hot-toast";
import { useSelector } from "react-redux";
import { mapBadgeExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import { useCallback } from "react";
import dayjs from "dayjs";
import ImageView from "../../../components/ImageView";
import ImageWithFallback from "../../../components/ImageWithFallback";

const BASE_URL = process.env.REACT_APP_API_BASE_URL || 'https://api.fitness-savage.mtechub.com/api/v1';

const Badges = () => {
  const theme = useTheme();
  const [badges, setBadges] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("created_at");
  const [order, setOrder] = useState("desc");
  const [searchTerm, setSearchTerm] = useState("");
  const [isExporting, setIsExporting] = useState(false);

  const [openViewModal, setOpenViewModal] = useState(false);
  const [openDeleteModal, setOpenDeleteModal] = useState(false);
  const [openAddEditModal, setOpenAddEditModal] = useState(false);
  const [selectedBadge, setSelectedBadge] = useState(null);
  const [badgeToDelete, setBadgeToDelete] = useState(null);
  const [badgeToEdit, setBadgeToEdit] = useState(null);
  const [isSaving, setIsSaving] = useState(false);

  const token = useSelector((state) => state.auth.token);

  const fetchBadges = useCallback(async () => {
    if (!token) return;
    setIsLoading(true);
    try {
      const queryParams = new URLSearchParams({
        page: page + 1,
        limit: rowsPerPage,
        sort_by: orderBy,
        sort_order: order,
        q: searchTerm,
      });

      const response = await fetch(`${BASE_URL}/badges?${queryParams.toString()}`, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const result = await response.json();
      if (response.ok && !result.error) {
        setBadges(result.data.badges || []);
        setTotalCount(result.data.pagination?.total || 0);
      } else {
        toast.error(result.message || "Failed to fetch badges");
      }
    } catch (error) {
      console.error("Fetch error:", error);
      toast.error("Error connecting to server");
    } finally {
      setIsLoading(false);
    }
  }, [token, page, rowsPerPage, orderBy, order, searchTerm]);

  useEffect(() => {
    fetchBadges();
  }, [fetchBadges]);

  const handleExport = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting badges as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const queryParams = new URLSearchParams({
        sort_by: orderBy,
        sort_order: order,
        q: searchTerm,
        not_pagination: "true",
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      });

      const response = await fetch(`${BASE_URL}/badges?${queryParams.toString()}`, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const result = await response.json();
      if (!response.ok || result.error) {
        throw new Error(result.message || "Failed to fetch badges for export");
      }

      const items = extractExportList(result, 'badges');
      const filename = `Badges_Export_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: mapBadgeExport,
        format,
        filename,
        sheetName: 'Badges',
        entityName: 'badges',
        toastId,
      });
    } catch (error) {
      console.error("Export error:", error);
      toast.error(error.message || "Connection error during export", { id: toastId });
    } finally {
      setIsExporting(false);
    }
  }, [token, orderBy, order, searchTerm]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  const handleViewDetails = (badge) => {
    setSelectedBadge(badge);
    setOpenViewModal(true);
  };

  const handleAddClick = () => {
    setBadgeToEdit(null);
    setOpenAddEditModal(true);
  };

  const handleEditClick = (badge) => {
    setBadgeToEdit(badge);
    setOpenAddEditModal(true);
  };

  const handleDeleteClick = (badge) => {
    setBadgeToDelete(badge);
    setOpenDeleteModal(true);
  };

  const handleConfirmDelete = async () => {
    if (!badgeToDelete || !token) return;
    const toastId = toast.loading("Deleting badge...");
    try {
      const response = await fetch(`${BASE_URL}/badges/${badgeToDelete.id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success(`"${badgeToDelete?.title}" Deleted Successfully!`, { id: toastId });
        fetchBadges();
      } else {
        toast.error(result.message || "Delete failed", { id: toastId });
      }
    } catch (error) {
      toast.error("Server error during delete", { id: toastId });
    } finally {
      setOpenDeleteModal(false);
      setBadgeToDelete(null);
    }
  };

  const handleSaveBadge = async (formData) => {
    if (!token) return;
    setIsSaving(true);
    const toastId = toast.loading(`${badgeToEdit ? 'Updating' : 'Creating'} badge...`);
    try {
      const url = badgeToEdit 
        ? `${BASE_URL}/badges/${badgeToEdit.id}`
        : `${BASE_URL}/badges`;
      
      const body = badgeToEdit
        ? {
            max_points: formData.max_points,
            badge_image: formData.badge_image,
            title: badgeToEdit.title,
            color: badgeToEdit.color,
            color_value: badgeToEdit.color_value,
          }
        : formData;

      const response = await fetch(url, {
        method: badgeToEdit ? "PUT" : "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });

      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success(`Badge ${badgeToEdit ? 'Updated' : 'Created'} Successfully!`, { id: toastId });
        setOpenAddEditModal(false);
        setBadgeToEdit(null);
        fetchBadges();
      } else {
        toast.error(result.message || "Save failed", { id: toastId });
      }
    } catch (error) {
      toast.error("Internal server error", { id: toastId });
    } finally {
      setIsSaving(false);
    }
  };

  const columns = [
    {
      id: "title",
      label: "Badge Info",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <Box
            sx={{
              width: 40,
              height: 40,
              borderRadius: "12px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              bgcolor: alpha(row.color_value || theme.palette.primary.main, 0.1),
              color: row.color_value || theme.palette.primary.main,
              overflow: "hidden",
            }}
          >
            <ImageWithFallback
              src={row.badge_image}
              alt={row.title}
              fallbackIcon={BadgeIcon}
              sx={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                fontSize: 24,
              }}
            />
          </Box>
          <Box>
            <Typography
              sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: "0.875rem" }}
            >
              {row.title}
            </Typography>
                      </Box>
        </Box>
      ),
    },
    {
      id: "max_points",
      label: "Required Coins",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
          <CoinIcon sx={{ fontSize: 16, color: "#FFCC00" }} />
          <Typography sx={{ color: "#FFCC00", fontWeight: 800, fontSize: "0.9rem" }}>
            {row.max_points} <span style={{ fontSize: '0.7rem', color: '#8B8D97' }}>coins</span>
          </Typography>
        </Box>
      ),
    },
    {
      id: "color",
      label: "Badge Color",
      sortable: false,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
          <Box 
            sx={{ 
              width: 14, 
              height: 14, 
              borderRadius: '50%', 
              bgcolor: row.color_value,
              boxShadow: `0 0 8px ${alpha(row.color_value || '#000', 0.5)}`
            }} 
          />
          <Typography sx={{ color: "#FFFFFF", fontSize: "0.875rem", textTransform: 'capitalize' }}>
            {row.color}
          </Typography>
        </Box>
      ),
    },
    {
      id: "created_at",
      label: "Date Created",
      render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.875rem" }}>
          {row.created_at
            ? new Date(row.created_at).toLocaleDateString("en-US", {
                month: "short",
                day: "numeric",
                year: "numeric",
              })
            : "-"}
        </Typography>
      ),
    },
    {
      id: "actions",
      label: "Actions",
      render: (row) => (
        <Box sx={{ display: "flex", gap: 1 }}>
          <Tooltip title="View Details">
            <IconButton
              size="small"
              onClick={() => handleViewDetails(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <ViewIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Edit">
            <IconButton
              size="small"
              onClick={() => handleEditClick(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <EditIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          {/* <Tooltip title="Delete">
            <IconButton
              size="small"
              onClick={() => handleDeleteClick(row)}
              sx={{
                color: "#FF5050",
                bgcolor: alpha("#FF5050", 0.1),
                "&:hover": { bgcolor: alpha("#FF5050", 0.2) },
              }}
            >
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Tooltip> */}
        </Box>
      ),
    },
  ];

  const badgeDetailsData = useMemo(() => {
    if (!selectedBadge) return [];
    return [
      { label: "Badge Title", value: selectedBadge.title },
      { label: "Required Coins", value: `${selectedBadge.max_points} Coins` },
      { label: "Color Name", value: selectedBadge.color, color: selectedBadge.color_value },
      { label: "Color Hex", value: selectedBadge.color_value, color: selectedBadge.color_value },
      {
        label: "Date Created",
        value: selectedBadge.created_at
          ? new Date(selectedBadge.created_at).toLocaleString()
          : "N/A",
      },
      {
        label: "Last Updated",
        value: selectedBadge.updated_at
          ? new Date(selectedBadge.updated_at).toLocaleString()
          : "N/A",
      },
    ];
  }, [selectedBadge]);

  return (
    <Box sx={{ p: { xs: 1, md: 3 } }}>
      <DataTable
        title="Manage Badges"
        columns={columns}
        data={badges}
        isLoading={isLoading}
        // onAddClick={handleAddClick}
        // addLabel="Add Badge"
        onExport={handleExport}
        isExporting={isExporting}
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        pagination={{
          page: page,
          rowsPerPage: rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No badges found"
         />

      {selectedBadge && (
        <DetailsModal
          open={openViewModal}
          onClose={() => setOpenViewModal(false)}
          title="Badge Details"
          data={badgeDetailsData}
          maxWidth="sm"
        >
          <Box sx={{ mt: 2, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
            <Box
              sx={{
                width: 120,
                height: 120,
                borderRadius: "24px",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                bgcolor: alpha(selectedBadge.color_value || theme.palette.primary.main, 0.1),
                color: selectedBadge.color_value || theme.palette.primary.main,
                overflow: "hidden",
                border: `2px solid ${alpha(selectedBadge.color_value || theme.palette.primary.main, 0.2)}`,
                boxShadow: `0 8px 16px ${alpha(selectedBadge.color_value || '#000', 0.2)}`
              }}
            >
              <ImageWithFallback
                src={selectedBadge.badge_image}
                alt={selectedBadge.title}
                fallbackIcon={BadgeIcon}
                sx={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  fontSize: 60,
                }}
              />
            </Box>
            <Typography variant="caption" sx={{ color: '#8B8D97', fontWeight: 600 }}>
              Official Badge Icon
            </Typography>
          </Box>
        </DetailsModal>
      )}

      <BadgeModal
        open={openAddEditModal}
        onClose={() => setOpenAddEditModal(false)}
        onSubmit={handleSaveBadge}
        initialData={badgeToEdit}
        loading={isSaving}
      />

      <ConfirmationModal
        open={openDeleteModal}
        onClose={() => setOpenDeleteModal(false)}
        onConfirm={handleConfirmDelete}
        title="Delete Badge?"
        message={`Are you sure you want to delete "${badgeToDelete?.title}"? This action cannot be undone.`}
        confirmText="Delete"
        confirmColor="error"
      />
    </Box>
  );
};

export default Badges;
