import React, { useState, useEffect } from 'react';
import { 
    Box, 
    TextField, 
    MenuItem, 
    Button, 
    useTheme,
    Typography,
    Divider,
    IconButton,
    Tooltip,
    Stack,
    alpha
} from '@mui/material';
import { Add as AddIcon, Delete as DeleteIcon, ColorLens as ColorIcon, InsertPhoto as PhotoIcon, LockOutlined } from '@mui/icons-material';
import BaseModal from '../BaseModal';
import FileUpload from '../FileUpload';
import { INPUT_BG, INPUT_FONT_SIZE, INPUT_HEIGHT } from '../../theme';

const BADGE_COLORS = [
    { label: 'Bronze', value: 'bronze', hex: '#CD7F32' },
    { label: 'Silver', value: 'silver', hex: '#C0C0C0' },
    { label: 'Gold', value: 'gold', hex: '#FFD700' },
    { label: 'Platinum', value: 'platinum', hex: '#E5E4E2' },
    { label: 'Diamond', value: 'diamond', hex: '#B9F2FF' },
];

const BadgeModal = ({ 
    open, 
    onClose, 
    onSubmit, 
    initialData = null, 
    loading = false 
}) => {
    const isEdit = !!initialData;
    const theme = useTheme();

    const readOnlyValueBoxSx = {
        width: '100%',
        height: INPUT_HEIGHT,
        minHeight: INPUT_HEIGHT,
        maxHeight: INPUT_HEIGHT,
        boxSizing: 'border-box',
        px: '14px',
        display: 'flex',
        alignItems: 'center',
        bgcolor: alpha(INPUT_BG, 0.55),
        backgroundImage: `linear-gradient(180deg, ${alpha('#fff', 0.03)} 0%, transparent 100%)`,
        borderRadius: '10px',
        border: `1px dashed ${alpha('#fff', 0.14)}`,
        fontSize: INPUT_FONT_SIZE,
        overflow: 'hidden',
        cursor: 'not-allowed',
        userSelect: 'none',
        opacity: 0.92,
    };

    const readOnlyFloatingLabelSx = {
        position: 'absolute',
        left: 0,
        top: 0,
        transform: 'translate(14px, -9px) scale(0.75)',
        transformOrigin: 'top left',
        zIndex: 1,
        fontSize: INPUT_FONT_SIZE,
        fontWeight: 600,
        color: alpha('#8B8D97', 0.85),
        bgcolor: theme.palette.background.paper,
        px: '6px',
        ml: '-3px',
        lineHeight: 1.25,
        pointerEvents: 'none',
        display: 'inline-flex',
        alignItems: 'center',
        gap: 0.5,
    };

    const readOnlyHelperSx = {
        mt: 0.75,
        ml: 1.5,
        fontSize: '0.7rem',
        color: alpha(theme.palette.text.secondary, 0.85),
        letterSpacing: '0.02em',
    };

    const [formData, setFormData] = useState({
        title: '',
        max_points: 0,
        badge_image: '',
        color: '',
        color_value: ''
    });

    useEffect(() => {
        if (open) {
            if (initialData) {
                setFormData({
                    title: initialData.title || '',
                    max_points: initialData.max_points || 0,
                    badge_image: initialData.badge_image || '',
                    color: initialData.color || '',
                    color_value: initialData.color_value || ''
                });
            } else {
                setFormData({
                    title: '',
                    max_points: 0,
                    badge_image: '',
                    color: '',
                    color_value: ''
                });
            }
        }
    }, [open, initialData]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        if (name === 'color') {
            const selectedColor = BADGE_COLORS.find(c => c.value === value);
            setFormData(prev => ({ 
                ...prev, 
                color: value, 
                color_value: selectedColor ? selectedColor.hex : '' 
            }));
        } else {
            setFormData(prev => ({ 
                ...prev, 
                [name]: name === 'max_points' ? (parseInt(value) || 0) : value 
            }));
        }
    };

    // Removed requirement field handlers as they are not in the API

    const handleSubmit = (e) => {
        e.preventDefault();
        onSubmit(formData);
    };

    const actions = (
        <Box sx={{ display: 'flex', gap: 2, width: '100%' }}>
            <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={loading}
                sx={{ 
                    color: 'text.secondary', 
                    boxShadow: 'none',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)'
                    }
                }}
            >
                Cancel
            </Button>
            <Button
                fullWidth
                variant="contained"
                onClick={handleSubmit}
                disabled={loading || !formData.title || !formData.color}
                sx={{ 
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    '&:hover': { bgcolor: '#3EB05D' },
                    '&.Mui-disabled': {
                        bgcolor: alpha('#4CC66E', 0.5),
                        color: 'rgba(255, 255, 255, 0.5)'
                    }
                }}
            >
                {loading ? 'Processing...' : (isEdit ? 'Save Changes' : 'Add Badge')}
            </Button>
        </Box>
    );

    // Removed renderDynamicFields

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={isEdit ? 'Edit Badge' : 'Add New Badge'}
            maxWidth="sm"
            actions={actions}
        >
            <Box 
                component="form" 
                onSubmit={handleSubmit} 
                sx={{ 
                    pt: 2,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 2.5,
                    width: '100%',
                }}
            >
                {/* Basic Details Section  edit mode uses static display (no inputs) so values cannot be re-enabled via devtools */}
                {isEdit ? (
                    <Box sx={{ position: 'relative', width: '100%', overflow: 'visible' }}>
                        <Box component="span" sx={readOnlyFloatingLabelSx}>
                            <LockOutlined sx={{ fontSize: 14, color: alpha('#8B8D97', 0.9) }} aria-hidden />
                            Badge Title
                            <Typography component="span" sx={{ color: 'error.main' }}>
                                *
                            </Typography>
                        </Box>
                        <Box sx={readOnlyValueBoxSx} aria-readonly="true">
                            <Typography
                                noWrap
                                title={formData.title}
                                sx={{
                                    color: alpha('#fff', 0.62),
                                    fontWeight: 500,
                                    fontSize: INPUT_FONT_SIZE,
                                    width: '100%',
                                }}
                            >
                                {formData.title}
                            </Typography>
                        </Box>
                        <Typography component="p" sx={readOnlyHelperSx}>
                            Locked  this badge name cannot be changed.
                        </Typography>
                    </Box>
                ) : (
                    <TextField
                        fullWidth
                        label="Badge Title"
                        name="title"
                        value={formData.title}
                        onChange={handleChange}
                        required
                        placeholder="e.g. Achievement Unlocked"
                    />
                )}

                <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start' }}>
                    <Box sx={{ flex: 1 }}>
                        <TextField
                            fullWidth
                            type="number"
                            label="Required Coins"
                            name="max_points"
                            value={formData.max_points}
                            onChange={handleChange}
                            required
                            placeholder="e.g. 1000"
                            InputProps={{
                                inputProps: { min: 0 }
                            }}
                        />
                        {isEdit ? (
                            <Typography component="p" sx={readOnlyHelperSx}>
                                Editable  you can change the coin threshold.
                            </Typography>
                        ) : null}
                    </Box>

                    {isEdit ? (
                        <Box sx={{ flex: 1, position: 'relative', minWidth: 0, overflow: 'visible' }}>
                            <Box component="span" sx={readOnlyFloatingLabelSx}>
                                <LockOutlined sx={{ fontSize: 14, color: alpha('#8B8D97', 0.9) }} aria-hidden />
                                Badge Type
                                <Typography component="span" sx={{ color: 'error.main' }}>
                                    *
                                </Typography>
                            </Box>
                            <Box sx={readOnlyValueBoxSx} aria-readonly="true">
                                {(() => {
                                    const opt = BADGE_COLORS.find((c) => c.value === formData.color);
                                    const hex = opt?.hex || formData.color_value;
                                    const label = opt?.label || formData.color || '-';
                                    return (
                                        <Box
                                            sx={{
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: 1.5,
                                                minWidth: 0,
                                                width: '100%',
                                                overflow: 'hidden',
                                            }}
                                        >
                                            <Box
                                                sx={{
                                                    width: 16,
                                                    height: 16,
                                                    flexShrink: 0,
                                                    borderRadius: '50%',
                                                    bgcolor: hex,
                                                    opacity: 0.75,
                                                    boxShadow: hex ? `0 0 6px ${alpha(hex, 0.35)}` : 'none',
                                                }}
                                            />
                                            <Typography
                                                noWrap
                                                title={label}
                                                sx={{ fontSize: INPUT_FONT_SIZE, color: alpha('#fff', 0.62) }}
                                            >
                                                {label}
                                            </Typography>
                                        </Box>
                                    );
                                })()}
                            </Box>
                            <Typography component="p" sx={readOnlyHelperSx}>
                                Locked  tier / type cannot be changed.
                            </Typography>
                        </Box>
                    ) : (
                        <TextField
                            fullWidth
                            select
                            label="Badge Type"
                            name="color"
                            value={formData.color}
                            onChange={handleChange}
                            required
                            sx={{ flex: 1 }}
                        >
                            {BADGE_COLORS.map((option) => (
                                <MenuItem key={option.value} value={option.value} sx={{ fontSize: '0.875rem' }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                                        <Box
                                            sx={{
                                                width: 16,
                                                height: 16,
                                                borderRadius: '50%',
                                                bgcolor: option.hex,
                                                boxShadow: `0 0 6px ${alpha(option.hex, 0.4)}`,
                                            }}
                                        />
                                        {option.label}
                                    </Box>
                                </MenuItem>
                            ))}
                        </TextField>
                    )}
                </Box>

                <Box sx={{ mt: 1 }}>
                    <Typography 
                        variant="caption" 
                        sx={{ 
                            color: 'text.secondary', 
                            fontWeight: 700, 
                            mb: 1.5, 
                            display: 'flex', 
                            alignItems: 'center',
                            gap: 1,
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        <PhotoIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Badge Icon / Image
                    </Typography>
                    <FileUpload 
                        folderName="badges"
                        maxSizeMB={5}
                        helperText="PNG, JPG or WEBP (max. 5MB)"
                        existingImageUrl={formData.badge_image}
                        onUploadSuccess={(url) => setFormData(prev => ({ ...prev, badge_image: url }))}
                        onRemove={() => setFormData(prev => ({ ...prev, badge_image: '' }))}
                    />
                </Box>
            </Box>
        </BaseModal>
    );
};

export default BadgeModal;
